package main

import (
	"errors"
	"fmt"
)

// ErrNotFound is a domain sentinel owned by this package.
var ErrNotFound = errors.New("not found")

// repo layer: translate a low-level miss into a wrapped domain sentinel.
func getUser(id int) error {
	return fmt.Errorf("repo: user %d: %w", id, ErrNotFound) // %w keeps the chain
}

// service layer: add business context, still preserving the chain.
func checkout(id int) error {
	if err := getUser(id); err != nil {
		return fmt.Errorf("checkout: %w", err)
	}
	return nil
}

func main() {
	err := checkout(42)
	fmt.Println(err)                         // full context, joined by ': '
	fmt.Println("is ErrNotFound:", errors.Is(err, ErrNotFound)) // walks the chain
	fmt.Println("== ErrNotFound:", err == ErrNotFound)          // false: wrapping broke ==
}

