import (
	"errors"
	"fmt"
)

type NotFoundError struct {
	Resource string
	ID       int
}

func (e *NotFoundError) Error() string {
	return fmt.Sprintf("%s %d not found", e.Resource, e.ID)
}

func load() error {
	return fmt.Errorf("load: %w", &NotFoundError{Resource: "user", ID: 7})
}

func main() {
	err := load()
	var nf *NotFoundError
	if errors.As(err, &nf) {          // walks the chain, binds nf on match
		fmt.Printf("missing %s with id %d\n", nf.Resource, nf.ID)
	} else {
		fmt.Println("some other error:", err)
	}
}

